import hashlib, importlib.util, json, subprocess
from pathlib import Path
root=Path.cwd()
out=root/'docs/verification/settings-activation/ordering-keepalive-qualification-integration'
spec=importlib.util.spec_from_file_location('links',root/'scripts/check-doc-links.py')
mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def subjects():
 sources=list(mod.sources())
 inputs=set(sources)|{root/'Taskfile.yml',root/'scripts/check-doc-links.py'}
 targets={}
 for p in sources:
  for href in mod.links(p):
   resolved=mod.resolve(p,href)
   if resolved is None: continue
   dest,anchor=resolved
   key=str(dest.relative_to(root)) if dest.is_relative_to(root) else str(dest)
   targets[key]={'exists':dest.exists(),'kind':'file' if dest.is_file() else 'directory' if dest.is_dir() else 'missing'}
   if anchor and dest.suffix=='.md' and dest.exists(): inputs.add(dest)
 return {'inputs':{str(p.relative_to(root)):digest(p) for p in sorted(inputs)},'targets':targets}
before=subjects()
cmd=['mise','exec','--','task','check:docs']
r=subprocess.run(cmd,text=True,capture_output=True)
after=subjects()
links={'command':cmd,'exit_code':r.returncode,'stdout':r.stdout,'stderr':r.stderr,'before':before,'after':after,'subjects_unchanged':before==after}
(out/'links.json').write_text(json.dumps(links,indent=2)+'\n')
print(json.dumps({k:v for k,v in links.items() if k not in ('before','after')},indent=2))
manifest_names=['docs/design/architecture/diagrams.json','docs/design/architecture/settings-activation/diagrams.json']
checks=[]
browser_inputs={}
for name in manifest_names:
 p=root/name; data=json.loads(p.read_text())
 ids=[d['id'] for d in data['diagrams']]
 groups=[g['id'] for g in data['groups']]
 assert len(ids)==len(set(ids)),name
 assert len(groups)==len(set(groups)),name
 for d in data['diagrams']:
  assert d['group'] in groups,(name,d['id'])
  for key in ['source','rendered']:
   if key in d: assert (p.parent/d[key]).is_file(),(name,d['id'],key)
 discussion=data.get('discussion',{})
 for did in discussion.get('diagramIds',[]): assert did in ids,(name,did)
 for upd in discussion.get('updatedDiagrams',[]): assert upd['id'] in ids,(name,upd)
 checks.append({'path':name,'sha256':digest(p),'diagram_count':len(ids),'group_count':len(groups),'result':'pass'})
for p in (root/'docs/design/architecture').rglob('*'):
 if p.is_file() and p.suffix in ('.mmd','.json','.html','.css','.js'): browser_inputs[str(p.relative_to(root))]=digest(p)
(out/'browser-inputs.json').write_text(json.dumps(browser_inputs,indent=2)+'\n')
(out/'manifests.json').write_text(json.dumps({'checks':checks,'scope':'Unique diagram/group identifiers, valid diagram groups, existing source/rendered files and valid discussion references.'},indent=2)+'\n')
print(json.dumps(checks,indent=2))
